    /**
     * The Playwright page is process-wide so TEST RUN and Page Scanner can share a deep same-job
     * state. Crossing Bot Jobs is a different ownership generation: navigate the already-open
     * page once to the new persisted endpoint, or close it fail-closed so the next scan cannot
     * attribute the previous bank's page to the new owner.
     */
    private void retargetSharedBrowserForActiveBotJob() {
        ARWebDriver sharedBrowser = ARWebDriver.getInstance();
        ARPlaywrightDriver activeBrowser = sharedBrowser.currentPlaywrightDriver();
        if (activeBrowser == null || !activeBrowser.isOpen()) return;

        String endpointUrl = selectedEndpointUrl();
        try {
            if (Strings.isNullOrEmpty(endpointUrl)
                    || !sharedBrowser.openBrowserForOwnerSwitch(
                            arPropertyManager.getProperty(ARPropertyEnum.BROWSER),
                            endpointUrl,
                            preScanOptionsConfig())) {
                throw new IllegalStateException(
                        "The selected Bot Job does not have an available browser endpoint");
            }
            log.info(
                    "Shared Playwright browser retargeted to Bot Job {} endpoint",
                    selectedBotJob.getId());
        } catch (RuntimeException retargetFailure) {
            try {
                sharedBrowser.closeBrowser();
            } catch (RuntimeException closeFailure) {
                retargetFailure.addSuppressed(closeFailure);
            }
            log.error(
                    "Shared Playwright browser could not follow Bot Job {}; the stale page was closed",
                    selectedBotJob.getId(),
                    retargetFailure);
        }
    }

    private void abortWorkspaceActivation(int botJobId) {
        try {
            suspendReactWorkspaceSurfaces(botJobId);
        } finally {
            BotJobWorkspaceController.getInstance().deactivate(workspaceControllerGeneration);
            botJobDetailsWorkspaceRegistry.close(botJobId);
            clearBotJobWorkspaceCaches();
        }
    }

    private boolean refreshGrids() {
        try {
            applyGridSnapshot(botJobWorkspaceService.refresh(selectedBotJob), !firstLoad);
            return true;
        } catch (BotJobWorkspaceService.WorkspaceLoadException error) {
            performMessage.errorMessageOperationFailed(error.error());
            return false;
        }
    }

    private void applyGridSnapshot(BotJobWorkspaceService.GridSnapshot snapshot, boolean publish) {
        reactSessionContext.updatePayload(selectedBotJob.getId(), ScannerWorkspaceSessions.BOT_JOB_TASKS, snapshot.botJobJson());
        reactSessionContext.updatePayload(selectedBotJob.getId(), ScannerWorkspaceSessions.COMPONENT_TASKS, snapshot.componentJson());
        if (!publish) return;
        com.allinweb.ch.socket.InstructionRealtimePublisher publisher =
                com.allinweb.ch.socket.InstructionRealtimePublisher.getInstance();
        publisher.publishSerializedSnapshot(
                selectedBotJob.getHomeBankingId(), ScannerWorkspaceSessions.BOT_JOB_TASKS, snapshot.botJobJson());
        publisher.publishSerializedSnapshot(
                selectedBotJob.getHomeBankingId(), ScannerWorkspaceSessions.COMPONENT_TASKS, snapshot.componentJson());
    }


