    private void withSharedScannerActivity(
            PreScanWorkflowService.Context context,
            String destinationSessionId,
            Runnable operation) {
        BotJobDetailsWorkspaceRegistry.Snapshot snapshot =
                botJobDetailsWorkspaceRegistry.require(context.botJobId());
        withSharedScannerActivity(
                context,
                snapshot.workspaceEpoch(),
                operation,
                message -> sendPreScanStatus(
                        destinationSessionId, context, "failed", message, 0));
    }

    private void withSharedScannerActivity(
            PreScanWorkflowService.Context context,
            long workspaceEpoch,
            Runnable operation,
            java.util.function.Consumer<String> unavailableSink) {
        try {
            botJobDetailsWorkspaceRegistry.require(context.botJobId(), workspaceEpoch);
            try (ExecutionPauseCoordinator.ScannerActivity ignored = executionPauseCoordinator.beginScannerActivity(
                    context.botJobId(), workspaceEpoch)) {
                operation.run();
            }
        } catch (IllegalStateException unavailable) {
            unavailableSink.accept(unavailable.getMessage());
        }
    }

    private PreScanWorkflowService.Sink pageMappingsRescanSink(
            String destinationSessionId,
            PreScanWorkflowService.Context context,
            long workspaceEpoch,
            String bindingEpoch,
            String requestId,
            boolean scrollPage,
            int scrollPages,
            java.util.concurrent.atomic.AtomicBoolean completed,
            Runnable completion) {
        return new PreScanWorkflowService.Sink() {
            @Override
            public void status(String status, String message, int elementCount) {
                String publishedStatus = "running".equalsIgnoreCase(status)
                                && message != null
                                && message.toLowerCase(java.util.Locale.ROOT)
                                        .contains("already in progress")
                        ? "failed"
                        : status;
                boolean terminal = "done".equalsIgnoreCase(publishedStatus)
                        || "empty".equalsIgnoreCase(publishedStatus)
                        || "failed".equalsIgnoreCase(publishedStatus);
                if (terminal) {
                    completePageMappingsRescan(completed, completion);
                }
                sendPageMappingsRescanStatus(
                        destinationSessionId,
                        context,
                        workspaceEpoch,
                        bindingEpoch,
                        requestId,
                        scrollPage,
                        scrollPages,
                        publishedStatus,
                        message,
                        elementCount);
            }

            @Override
            public void reset() {
                // Page Mappings keeps the selected immutable capture visible while rescanning.
            }

            @Override
            public void elements(List<ElementDTO> elements) {
                // The new immutable capture is loaded through pageMappings.bootstrap/capture.
            }

            @Override
            public void failure(String message) {
                // PreScanWorkflowService always emits the terminal failed status first.
            }
        };
    }

    private static boolean completePageMappingsRescan(
            java.util.concurrent.atomic.AtomicBoolean completed, Runnable completion) {
        if (!completed.compareAndSet(false, true)) return false;
        completion.run();
        return true;
    }

    private void sendPageMappingsRescanStatus(
            String destinationSessionId,
            PreScanWorkflowService.Context context,
            long workspaceEpoch,
            String bindingEpoch,
            String requestId,
            boolean scrollPage,
            int scrollPages,
            String status,
            String message,
            int elementCount) {
        JsonObject payload = new JsonObject();
        payload.addProperty("requestId", requestId);
        payload.addProperty("bindingEpoch", bindingEpoch);
        payload.addProperty("workspaceEpoch", workspaceEpoch);
        payload.addProperty("homeBankingId", context.homeBankingId());
        payload.addProperty("botJobId", context.botJobId());
        payload.addProperty("scrollPage", scrollPage);
        payload.addProperty("scrollPages", scrollPages);
        payload.addProperty("status", status);
        payload.addProperty("message", message == null ? "" : message);
        payload.addProperty("elementCount", elementCount);
        webSocketSessionManager.sendMessageJson(
                context.homeBankingId(),
                destinationSessionId,
                payload.toString(),
                "pageMappings.rescanStatus");
    }

    private PreScanWorkflowService.Context detachedPageScannerContext(int botJobId) {
        if (selectedBotJob == null
                || selectedBotJob.getId() == null
                || selectedBotJob.getId() != botJobId) {
            throw new IllegalArgumentException("Page Scanner does not match the active Bot Job");
        }
        botJobDetailsWorkspaceRegistry.require(botJobId);
        workspaceCapabilities.requirePreScan(selectedBotJob.getPriority());
        return preScanContext();
    }

    private PreScanWorkflowService.Context preScanContext() {
        return new PreScanWorkflowService.Context(
                selectedBotJob.getId(),
                selectedBotJob.getName(),
                selectedBotJob.getHomeBankingId(),
                selectedBotJob.getHomeUrlId(),
                selectedEndpointUrl(),
                arPropertyManager.getProperty(ARPropertyEnum.BROWSER),
                preScanOptionsConfig(),
                arPropertyManager.getProperty(ARPropertyEnum.PATH_DB));
    }

    /**
     * Detached Page Scanner bindings keep immutable Bot Job identity, but the global browser
     * selection is live configuration and must be resolved again for every future browser action.
     */
    private PreScanWorkflowService.Context withCurrentConfiguredBrowser(
            PreScanWorkflowService.Context context) {
        String configuredBrowser = arPropertyManager.getProperty(ARPropertyEnum.BROWSER);
        if (configuredBrowser == null) configuredBrowser = "";
        if (configuredBrowser.equalsIgnoreCase(
                context.browserType() == null ? "" : context.browserType())) {
            return context;
        }
        return new PreScanWorkflowService.Context(
                context.botJobId(),
                context.botJobName(),
                context.homeBankingId(),
                context.homeUrlId(),
                context.endpointUrl(),
                configuredBrowser,
                context.optionsConfig(),
                context.jsonPath());
    }

    private PreScanWorkflowService.Sink preScanSink() {
        return preScanSink(preScanPayloadService.destinationSessionId());
    }

