    private void runTestRunFromReact(
            BotJobToolbarContext context,
            BotJobDetailsRequest request,
            BotJobToolbarAction action,
            CompletableFuture<BotJobToolbarActionResult> completion) {
        requireDesktopBrowserExecution(context);
        TestRunRequestSelection requested = resolveTestRunRequest(context, request.body());
        JsonObject body = request.body();
        String mode = requested.mode();
        RunScope runScope = requested.runScope();

        ScannerExecutionPreflightMonitor.Observation preflightObservation =
                observeTestRunPreflight(context, runScope);
        ExecutionPreflightReport preflightReport =
                ExecutionPreflightReport.from(preflightObservation);
        if (preflightBlocksStart(preflightReport)) {
            completion.complete(BotJobToolbarActionResult.failure(
                            action, preflightMessage(preflightReport, true))
                    .withExecutionPreflight(preflightReport));
            return;
        }

        JsonObject excelWorkspace = ExcelDataWorkspaceService.getInstance()
                .openForBotJob(context.botJobId());
        if (excelWorkspace == null
                || !excelWorkspace.has("ok")
                || !excelWorkspace.get("ok").getAsBoolean()) {
            throw new IllegalStateException(
                    excelWorkspace != null && excelWorkspace.has("error")
                            ? excelWorkspace.get("error").getAsString()
                    : "Excel Data memory could not be opened for TEST RUN");
        }
        JsonObject excelPolicy = ExcelDataWorkspaceService.getInstance()
                .applyExecutionMode(context.botJobId());
        if (!excelPolicy.get("ok").getAsBoolean()) {
            throw new IllegalStateException(excelPolicy.get("error").getAsString());
        }
        prepareRuntimeMemoryForExecution(context, body);
        BotJobTestRunCoordinator.StartResult result;
        try (ExecutionPauseCoordinator.ExecutionStart ignored =
                executionPauseCoordinator.reserveExecutionStart()) {
            result = botJobTestRunCoordinator.start(
                    context,
                    requested.executionSelection().blockOrderNumber(),
                    requested.executionSelection().runSingleBlock(),
                    mode,
                    requested.blockName(),
                    request.requestId());
        }
        if (result.accepted()) {
            JsonObject runtimeOpen = VariablesWorkspaceService.getInstance()
                    .openRuntimeVariablesForBotJob(context.botJobId());
            if (!runtimeOpen.has("ok") || !runtimeOpen.get("ok").getAsBoolean()) {
                log.warn(
                        "Runtime Variables could not be opened for TEST RUN Bot Job {}",
                        context.botJobId());
            }
        }
        completion.complete((result.accepted()
                ? BotJobToolbarActionResult.success(action, result.message())
                : BotJobToolbarActionResult.failure(action, result.message()))
                .withExecutionPreflight(preflightReport));
    }

    private void runTestRunPreflightFromReact(
            BotJobToolbarContext context,
            BotJobDetailsRequest request,
            CompletableFuture<BotJobToolbarActionResult> completion) {
        TestRunRequestSelection requested = resolveTestRunRequest(context, request.body());
        ExecutionPreflightReport report = ExecutionPreflightReport.from(
                observeTestRunPreflight(context, requested.runScope()));
        BotJobToolbarActionResult result = preflightBlocksStart(report)
                ? BotJobToolbarActionResult.failure(
                        BotJobToolbarAction.PREFLIGHT, preflightMessage(report, false))
                : BotJobToolbarActionResult.success(
                        BotJobToolbarAction.PREFLIGHT, preflightMessage(report, false));
        completion.complete(result.withExecutionPreflight(report));
    }

    private ScannerExecutionPreflightMonitor.Observation observeTestRunPreflight(
            BotJobToolbarContext context,
            RunScope runScope) {
        botJobDetailsWorkspaceRegistry.require(context.botJobId(), context.workspaceEpoch());
        return executionPreflightMonitor.observe(
                "BOT_JOB_DETAILS_TEST_RUN",
                context.executionBotJob(),
                runScope);
    }

    private TestRunRequestSelection resolveTestRunRequest(
            BotJobToolbarContext context,
            JsonObject body) {
        String mode = requiredString(body, "executionMode").toUpperCase(java.util.Locale.ROOT);
        if (!"ALL".equals(mode) && !"ONE".equals(mode)) {
            throw new IllegalArgumentException("Execution mode must be ALL or ONE");
        }

        int blockId = optionalInt(body, "blockId", 0);
        boolean executeAllSelected = blockId <= 0;
        if (executeAllSelected && "ONE".equals(mode)) {
            throw new IllegalArgumentException("Select a numbered block before using ONE mode");
        }

        Integer blockOrder = null;
        String blockName = EXECUTE_ALL_OPTION_LABEL;
        if (!executeAllSelected) {
            ErrorMessage loadError = performDataBase.loadBlocks(context.botJobId(), "", "block");
            if (loadError != null) throw new IllegalStateException(botJobErrorText(loadError));
            BlockLoadDTO selectedBlock = performLists.getListBlock().stream()
                    .filter(block -> block != null
                            && block.getId() != null
                            && block.getId() == blockId
                            && context.botJobId() == block.getBotJobId())
                    .findFirst()
                    .orElseThrow(() -> new IllegalArgumentException("The selected block is no longer available"));
            blockOrder = selectedBlock.getBlockOrderNumber();
            blockName = selectedBlock.getName();
        }

        TestRunExecutionSelection selection = TestRunExecutionSelection.resolve(
                blockOrder, executeAllSelected, "ONE".equals(mode));
        RunScope runScope = executeAllSelected
                ? RunScope.all()
                : "ONE".equals(mode)
                        ? RunScope.one(blockId)
                        : RunScope.fromBlock(blockId);
        return new TestRunRequestSelection(mode, blockName, selection, runScope);
    }

    private static boolean preflightBlocksStart(ExecutionPreflightReport report) {
        return report == null
                || "BLOCKED".equals(report.outcome())
                || "UNAVAILABLE".equals(report.outcome());
    }

    private static String preflightMessage(
            ExecutionPreflightReport report,
            boolean startAttempt) {
        String prefix = startAttempt ? "TEST RUN was not started. " : "";
        if (report == null || "UNAVAILABLE".equals(report.outcome())) {
            String reason = report == null ? null : report.unavailableReason();
            return prefix + "Test Run preflight is unavailable"
                    + (Strings.isNullOrEmpty(reason) ? "." : ": " + reason);
        }
        if ("BLOCKED".equals(report.outcome())) {
            int count = report.structuralStartFailureCount();
            return prefix + count + " structural start failure"
                    + (count == 1 ? " was" : "s were") + " detected.";
        }
        if ("WARN".equals(report.outcome())) {
            int count = report.variableDiagnosticCount();
            return "Test Run preflight completed with " + count + " variable diagnostic"
                    + (count == 1 ? "." : "s.");
        }
        return "Test Run preflight passed.";
    }

    private record TestRunRequestSelection(
            String mode,
            String blockName,
            TestRunExecutionSelection executionSelection,
            RunScope runScope) {}

    /** LAUNCH now owns the same in-process Playwright runtime, progress stream, and PAUSE protocol. */
    private void runLaunchFromReact(
            BotJobToolbarContext context,
            BotJobDetailsRequest request,
            BotJobToolbarAction action,
            CompletableFuture<BotJobToolbarActionResult> completion) {
        requireDesktopBrowserExecution(context);
        File workbook = botJobNativeOperations.excelDestination(context);
        if (!workbook.isFile()) {
            throw new IllegalStateException("Generate the Excel file before launching the Bot Job");
        }
        JsonObject excelPolicy = ExcelDataWorkspaceService.getInstance()
                .validateLaunchDataSaved(context.botJobId());
        if (!excelPolicy.get("ok").getAsBoolean()) {
            throw new IllegalStateException(excelPolicy.get("error").getAsString());
        }
        prepareRuntimeMemoryForExecution(context, request.body());
        ScannerExecutionPreflightMonitor.Observation preflightObservation =
                executionPreflightMonitor.observe(
                        "BOT_JOB_DETAILS_LAUNCH",
                        context.executionBotJob(),
                        RunScope.all());
        BotJobTestRunCoordinator.StartResult result;
        try (ExecutionPauseCoordinator.ExecutionStart ignored =
                executionPauseCoordinator.reserveExecutionStart()) {
            result = botJobTestRunCoordinator.start(
                    context,
                    1,
                    false,
                    "ALL",
                    EXECUTE_ALL_OPTION_LABEL,
                    request.requestId());
        }
        String message = result.message().replace("TEST RUN", "LAUNCH");
        completion.complete(result.accepted()
                ? BotJobToolbarActionResult.success(action, message)
                        .withExecutionPreflight(
                                ExecutionPreflightReport.from(preflightObservation))
                : BotJobToolbarActionResult.failure(action, message));
    }

    /**
     * Loads the committed runtime-variable snapshot before execution and applies an explicit RESET
     * policy when requested.
     *
     * <p>Variables are optional execution support: a storage outage is reported to the log but
     * never blocks navigation or a test run. The process-local registry is only a read cache and is
     * replaced after the database transaction commits.
     */
    private void prepareRuntimeMemoryForExecution(
            BotJobToolbarContext context, JsonObject body) {
        RuntimeMemoryPolicy policy = RuntimeMemoryPolicy.parse(
                body == null || !body.has("runtimeMemoryPolicy")
                                || body.get("runtimeMemoryPolicy").isJsonNull()
                        ? null
                        : body.get("runtimeMemoryPolicy").getAsString());
        OwnerKey owner = new OwnerKey(context.homeBankingId(), context.botJobId());
        try (Connection connection = performDataBase.getConnection()) {
            Snapshot snapshot;
            if (policy == RuntimeMemoryPolicy.RESET) {
                MutationResult reset =
                        runtimeVariableService.resetForExecution(connection, owner, null);
                snapshot = reset.snapshot();
                if (!reset.applied() || snapshot == null) {
                    log.warn(
                            "Runtime memory RESET was not applied for Bot Job {}: {}",
                            context.botJobId(),
                            reset.message());
                    snapshot = runtimeVariableService.hydrate(connection, owner);
                }
            } else {
                snapshot = runtimeVariableService.hydrate(connection, owner);
            }
            RuntimeVariableMemoryRegistry.getInstance().hydrateDurableSnapshot(snapshot);
        } catch (SQLException | RuntimeException unavailable) {
            log.warn(
                    "Runtime variable memory is unavailable for Bot Job {}; execution will continue with VOID/last committed cache: {}",
                    context.botJobId(),
                    unavailable.getMessage());
        }
    }

    private void requireDesktopBrowserExecution(BotJobToolbarContext context) {
        if (!workspaceCapabilities.supportsDesktopBrowserTools(context.projectType())) {
            throw new IllegalStateException("Mobile Bot Jobs can only be executed from AR Mobile");
        }
    }

    private File openExcelFromReact(BotJobToolbarContext context) throws IOException {
        File excel = botJobNativeOperations.openExcel(context);
        log.info("Excel file opened: {}", excel.getAbsolutePath());
        return excel;
    }

    private File generateExcelFromReact(BotJobToolbarContext context, JsonObject body) throws Exception {
        ErrorMessage error = null;
        if (performLists.getQuickBotJobs().isEmpty()) error = performDataBase.loadQuickBotJobs();
        if (error == null) error = performDataBase.loadBlocks(context.botJobId(), context.name(), "block");
        if (error == null) error = performDBEngine.loadAllActionsPerBlock(performLists.getListBlock());
        if (error != null) throw new IllegalStateException(botJobErrorText(error));

        String workbookName = context.name().trim();
        File expected = botJobNativeOperations.excelDestination(context);
        ExtractedData extracted = ExcelUtils.isFileExists(workbookName, performLists.getAllActions());
        if (extracted != null && extracted.getErrorMessage() != null) {
            throw new IllegalStateException(extracted.getErrorMessage());
        }
        if (extracted != null && !booleanValue(body, "confirmed", false)) {
            throw new IllegalArgumentException("Confirm replacement of the existing Excel file");
        }
        File generated = new ExcelUtils().generateExcelFiles(extracted, workbookName, null, false);
        if (!generated.isFile() || generated.length() == 0L) {
            throw new IllegalStateException("Excel generation did not produce a file");
        }
        if (!generated.getCanonicalFile().equals(expected.getCanonicalFile())) {
            throw new IllegalStateException("Excel generation produced an unexpected file");
        }
        File opened = botJobNativeOperations.openFile(generated);
        log.info("Excel file generated and opened: {}", opened.getAbsolutePath());
        return opened;
    }

    private File chooseReportFromReact(JsonObject body) throws IOException {
        String requestedPath = optionalString(body, "reportPath");
        File selected = requestedPath.isEmpty()
                ? presentation().chooseReport(botJobNativeOperations.reportDirectory())
                : new File(requestedPath);
        return botJobNativeOperations.selectReport(selected);
    }

    private void exportJobFromReact(BotJobToolbarContext context, BotJobDetailsRequest request) {
        requireConfirmed(request.body(), "Confirm the Bot Job export");
        String path = botJobTransferPathRegistry.require(
                request.sessionId(), context.botJobId(), requiredString(request.body(), "transferPath"));
        BotJobTransferResult result = botJobTransferService.exportJob(
                context.homeBankingId(), context.botJobId(), path);
        if (!result.ok()) throw new IllegalStateException(result.message());
    }

    private void importJobFromReact(BotJobToolbarContext context, BotJobDetailsRequest request) {
        requireConfirmed(request.body(), "Confirm the Bot Job import");
        String path = botJobTransferPathRegistry.require(
                request.sessionId(), context.botJobId(), requiredString(request.body(), "transferPath"));
        String dateText = requiredString(request.body(), "restoreDate");
        LocalDate restoreDate;
        try {
            restoreDate = LocalDate.parse(dateText);
        } catch (RuntimeException invalidDate) {
            throw new IllegalArgumentException("Restore date must use YYYY-MM-DD", invalidDate);
        }
        BotJobTransferResult result = botJobTransferService.importJob(
                context.homeBankingId(),
                context.organizationName(),
                context.homeUrlId(),
                context.botJobId(),
                restoreDate,
                path);
        if (!result.ok()) throw new IllegalStateException(result.message());
        if (!refreshGrids()) {
            throw new IllegalStateException("Bot Job imported but the instruction grids could not be refreshed");
        }
    }

