    public void destroy() {
        if (selectedBotJob != null && selectedBotJob.getId() != null) {
            suspendReactWorkspaceSurfaces(selectedBotJob.getId());
        }
        BotJobWorkspaceController.getInstance().deactivate(workspaceControllerGeneration);
        instance = null;
    }

    private boolean checkLicense() {
        try {
            String licensePath = arPropertyManager.getProperty(ARPropertyEnum.PATH_LICENSE);
            if (Strings.isNullOrEmpty(licensePath)) {
                licensePath = System.getProperty("user.dir");
            }

            LicenceVal licenseStatus = LicenseManager.checkLicenseFile(licensePath);

            String msgValid = "The license file is valid and the application is authorized for use.";
            String msgNextStep = "You can now proceed with normal application usage.";

            String msgColor = "#0277BD";
            if (!licenseStatus.equals(LicenceVal.VALID)) {
                msgValid = "The license file is not valid and the application is not authorized for use.";
                msgNextStep = "Application access is restricted. Please obtain a valid license to continue.";
                msgColor = "#C62828"; // Soft, elegant red tone

                performMessage.showCustomModalDialogDragWin11(
                        "License Status Verification",
                        "<span style='color: #2E7D32; font-weight: bold; font-size: 1.1em;'>License status has been successfully verified.</span>",
                        "<span style='color: " + msgColor + "; font-weight: bold;'>" + msgValid + "</span>",
                        "<span style='font-style: italic;'>" + msgNextStep + "</span>",
                        "<span style='color: #E65100; font-weight: bold;'>Current license status:</span> <span style='font-weight: bold;'>"
                                + licenseStatus.getStaus() + "</span>",
                        false,
                        "OK",
                        null,
                        0);
                return false;
            }
            return true;
        } catch (Exception error) {

            log.error("Cannot read/validate the License path/file. Error: " + error.getMessage());
            return false;
        }
    }

    // Allow the stage to be set from outside when pane is shown
    // 🔹 Method to close the window
    private void closePane() {
        if (!canCloseWorkspace()) {
            throw new IllegalStateException(
                    "Wait for the active Bot Job operation to finish or stop TEST RUN first");
        }
        markWorkspaceClosed();
        presentation().showMainDashboard();
    }

    public void markWorkspaceClosed() {
        workspaceCloseCoordinator.close(
                selectedBotJob == null ? null : selectedBotJob.getId());
        BotJobWorkspaceController.getInstance().deactivate(workspaceControllerGeneration);
    }

    public boolean canCloseWorkspace() {
        return workspaceCloseCoordinator.canClose(
                selectedBotJob == null ? null : selectedBotJob.getId());
    }

    public boolean closeWorkspaceIfIdle() {
        if (!canCloseWorkspace()) return false;
        markWorkspaceClosed();
        return true;
    }

    /**
     * Force-stops resources owned by Bot Job Details during terminal application shutdown. Unlike a
     * user closing this one workspace, application shutdown must not be blocked by an active toolbar
     * operation or TEST RUN.
     */
    public void shutdownForApplication() {
        shutdownStage("external Engine", botJobToolbarGuard::terminateExternalEngine);
        shutdownStage("toolbar executor", botJobToolbarExecutor::shutdownNow);
        shutdownStage("detached Page Scanner queue", detachedPageScannerTaskGate::shutdownNow);
        shutdownStage("Pre Scan browser", this::closePageScannerOperations);
        shutdownStage("scanner shell", scannerCoordinator::close);

        Integer botJobId = selectedBotJob == null ? null : selectedBotJob.getId();
        if (botJobId != null && botJobId > 0) {
            shutdownStage("Bot Job React surfaces", () -> suspendReactWorkspaceSurfaces(botJobId));
            shutdownStage("Bot Job workspace registry", () -> botJobDetailsWorkspaceRegistry.close(botJobId));
        }
        shutdownStage(
                "Bot Job workspace controller",
                () -> BotJobWorkspaceController.getInstance().deactivate(workspaceControllerGeneration));
    }

    private static void shutdownStage(String resource, Runnable close) {
        try {
            close.run();
        } catch (RuntimeException failure) {
            log.warn("Unable to stop {} during application shutdown: {}", resource, failure.getMessage());
        }
    }

